#!/usr/bin/env python3
import sys


def read_variants(path, limit):
    variants = []
    with open(path, "rt", encoding="utf-8") as handle:
        for line in handle:
            if not line or line.startswith("#"):
                continue
            fields = line.rstrip("\n").split("\t")
            if len(fields) < 5:
                raise ValueError("VCF record has fewer than five columns")
            chrom, pos, ref, alt = fields[0], int(fields[1]), fields[3].upper(), fields[4].upper()
            if chrom not in ("20", "chr20"):
                raise ValueError(f"Unexpected chromosome: {chrom}")
            if len(ref) != 1 or len(alt) != 1 or ref not in "ACGT" or alt not in "ACGT":
                raise ValueError(f"Non-biallelic-SNP record at {chrom}:{pos}")
            variants.append((pos, ref))
            if limit and len(variants) >= limit:
                break
    return variants


def read_single_fasta(path):
    sequence_parts = []
    names = []
    with open(path, "rt", encoding="ascii") as handle:
        for line in handle:
            if line.startswith(">"):
                names.append(line[1:].strip().split()[0])
            else:
                sequence_parts.append(line.strip())
    if len(names) != 1:
        raise ValueError(f"Expected one FASTA sequence in {path}, found {len(names)}")
    return names[0], "".join(sequence_parts).upper()


def count_matches(variants, sequence, shift, complement=False):
    comp = str.maketrans("ACGT", "TGCA")
    in_range = matches = 0
    for pos, ref in variants:
        index = pos - 1 + shift
        if 0 <= index < len(sequence):
            in_range += 1
            tested_ref = ref.translate(comp) if complement else ref
            matches += tested_ref == sequence[index]
    return in_range, matches


def main():
    if len(sys.argv) != 9:
        raise SystemExit("usage: script.py VCF HG18 HG19 HG38 T2T LIMIT OUT")
    vcf, hg18, hg19, hg38, t2t, limit_text, output = sys.argv[1:]
    limit = int(limit_text)
    variants = read_variants(vcf, limit)
    if not variants:
        raise ValueError("No variants found")
    references = [("hg18", hg18), ("hg19", hg19), ("hg38", hg38), ("T2T-CHM13", t2t)]
    rows = []
    for build, fasta in references:
        seq_name, sequence = read_single_fasta(fasta)
        in_range, exact = count_matches(variants, sequence, 0)
        _, left = count_matches(variants, sequence, -1)
        _, right = count_matches(variants, sequence, 1)
        _, complement = count_matches(variants, sequence, 0, complement=True)
        rows.append((build, seq_name, len(sequence), len(variants), in_range, exact, left, right, complement))
    rows.sort(key=lambda row: (-row[5], row[0]))
    with open(output, "wt", encoding="utf-8") as handle:
        handle.write("build\tsequence_name\tsequence_length\tvariants_tested\tin_range\texact_1based_matches\texact_1based_rate\tminus1_matches\tplus1_matches\tcomplement_matches\n")
        for row in rows:
            build, seq_name, seq_len, tested, in_range, exact, left, right, complement = row
            rate = exact / in_range if in_range else 0.0
            handle.write(f"{build}\t{seq_name}\t{seq_len}\t{tested}\t{in_range}\t{exact}\t{rate:.9f}\t{left}\t{right}\t{complement}\n")


if __name__ == "__main__":
    main()

